async function saveBudgetChoice(id,patch){
    if(budgetChoiceSaving.has(id)||!canChooseBudget())return;const iid=state.data.iteration.id;budgetChoiceSaving.add(id);document.querySelectorAll(`[data-budget-row="${CSS.escape(id)}"] input`).forEach(el=>el.disabled=true);updateBudgetChoiceDisplay('Saving your budget choices…');
    try{const result=await api('budget_choice',{iteration:iid,id,...patch});if(state.data?.iteration.id!==iid)return;const row=result.budget.find(x=>x.id===id);const index=state.data.budget.findIndex(x=>x.id===id);if(index>=0&&row)state.data.budget[index]=row;updateBudgetChoiceDisplay('Saved · Your design team can see these budget choices.');}
    catch(error){if(state.data?.iteration.id===iid){try{await refresh(true);}catch{}updateBudgetChoiceDisplay('Not saved. Please try again.');}toast(error.message);}
    finally{budgetChoiceSaving.delete(id);if(state.data?.iteration.id===iid)document.querySelectorAll(`[data-budget-row="${CSS.escape(id)}"] input`).forEach(el=>el.disabled=!canChooseBudget());}
}
document.addEventListener('input',e=>{const id=e.target.dataset.budgetRange;if(!id||!canChooseBudget())return;const item=state.data.budget.find(x=>x.id===id);if(item){item.range_percent=Number(e.target.value);updateBudgetChoiceDisplay();}});
document.addEventListener('change',e=>{const range=e.target.dataset.budgetRange,option=e.target.dataset.budgetOption,id=range||option;if(!id||!canChooseBudget())return;const item=state.data.budget.find(x=>x.id===id);if(!item)return;const patch=range?{range_percent:Number(e.target.value)}:{selected:e.target.checked};Object.assign(item,patch);saveBudgetChoice(id,patch);});
function chatPanel(){return `<aside class="chat-panel"><div class="chat-heading"><h3>${icon('spark')}Budget & scope questions</h3><p>Ask about costs, inclusions and your legal documents.</p></div><div class="chat-body" id="chat-messages">${state.chat.length?state.chat.map(m=>`<div class="chat-message ${m.role}">${esc(m.text)}${m.citations?.length?`<div class="sources">${m.citations.map(c=>`<button data-action="legal-citation" data-version="${esc(c.version_id)}" data-page="${c.page}">${icon('file')}${esc(c.name)} · p. ${c.page}</button>`).join('')}</div>`:''}${m.sources?.length?`<div class="sources">${m.sources.map((s,i)=>`<button data-action="download" data-id="${esc(s)}">${icon('file')}Source ${i+1}</button>`).join('')}</div>`:''}</div>`).join(''):'<p class="chat-empty">Ask about your project’s costs or scope.</p>'}${state.busy?'<span class="loading-inline" aria-label="Preparing answer"></span>':''}</div><form class="chat-form" data-form="chat"><input name="question" placeholder="Ask a question…" aria-label="Ask about costs and scope" required maxlength="2000"><button aria-label="Send question" ${state.busy?'disabled':''}>${icon('up')}</button></form><p class="chat-footer">${state.data.capabilities.ai?'AI answers · check linked sources':'Budget helper · AI connection not enabled'}</p></aside>`;}
