 return `<p class="slide-label">Your next chapter</p><h1 class="slide-heading">${esc(def.title)}</h1><div class="summary-layout"><div><p class="slide-description">${esc(def.description??'Take a little time to imagine yourself here. Your design, the details and the numbers are all in one place.')}</p><div class="summary-stats"><div><strong>${money(d.total_cents)}</strong><span>Known investment</span></div><div><strong>${d.files.length}</strong><span>Source files</span></div></div>${button('Share your thoughts','feedback','primary','','chat')}<p class="budget-note">${d.budget.filter(x=>budgetAmount(x)===null).length} costs remain unspecified. This presentation does not replace the original drawings or vendor quotes.</p></div><div class="download-list"><h3>Yours to keep</h3>${d.files.map(f=>`<button data-action="history" data-id="${esc(f.id)}"><span>${esc(f.name)}<small>${cats[f.category]} · Version ${f.number} · Originals & history</small></span>${icon('download')}</button>`).join('')||'<p class="budget-note">Files will appear here once added.</p>'}</div></div>`;
