 openModal('Studio settings',`<p>Workspace appearance is fixed: Warm grayscale, editorial style and serif titles. Project presentation styles are set per project.</p><div class="studio-logo-settings">${state.studio?.has_logo?`<img class="studio-logo" src="${studioLogoUrl()}" alt="Current studio logo">`:'<span class="muted">No studio logo yet</span>'}<form data-form="studio-logo"><label>Studio logo<input name="logo" type="file" accept="image/png,image/jpeg,image/webp" required></label><small>PNG, JPEG or WebP · up to 2 MB</small><div class="row">${state.studio?.has_logo?button('Remove logo','remove-studio-logo','small'):''}<button class="button small" type="submit">Upload logo</button></div></form></div><form data-form="studio-theme"><label>Studio name<input name="name" value="${esc(state.studio?.name||'')}" maxlength="100" required></label>${formFooter('Save studio settings')}</form>`);state.settingsOpen=true;syncWorkspaceUrl();
