    let root=$('#photo-lightbox');if(!root){root=document.createElement('div');root.id='photo-lightbox';root.className='photo-lightbox';root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');root.setAttribute('aria-label','Full-screen image');document.body.append(root);}
