        root.innerHTML=`<header class="photo-lightbox-header"><div><strong>${esc(def.title)}</strong><span>${esc(slideTypeName(def))} · ${esc(situations[def.situation]||'Source image')}</span></div><button class="icon-button" data-action="close-photo" aria-label="Close full-screen image">${icon('close')}</button></header><div class="photo-lightbox-stage"><button class="icon-button photo-lightbox-prev" data-action="previous-photo-slide" aria-label="Previous slide" ${state.slide===0?'disabled':''}>${icon('left')}</button><figure>${visualImageArea(def,f,true)}</figure><button class="icon-button photo-lightbox-next" data-action="next-photo-slide" aria-label="Next slide" ${state.slide===defs.length-1?'disabled':''}>${icon('right')}</button></div><footer><span>${state.slide+1} / ${defs.length}</span><span>← → Navigate slides · Esc to close</span><small>Presented by studiodeck</small></footer>`;
