function applySession(session){state.user=session.user;state.capabilities=session.capabilities;state.unreadCount=session.unread_count||0;state.csrf=session.csrf;state.studio=session.studio;state.studios=session.studios;state.studioTheme=cleanStudioTheme(session.studio_theme||{});}
async function resetStudio(){clearTimeout(state.poll);imageCache.forEach(url=>{if(url.startsWith('blob:'))URL.revokeObjectURL(url);});imageCache.clear();state.data=null;state.present=false;state.tab='projects';state.studioUsers=[];state.projectSearch='';state.showArchived=false;state.projects=(await api('projects')).projects;render();pollJobs();}
function studioUsersPage(){return `<div class="project-head"><div><h1>Studio users</h1><p class="muted">${esc(state.studio?.name)} · Admins can manage members. Project access comes from project teams.</p></div>${state.studio?.role==='admin'?button('Add user','edit-studio-user','primary','','plus'):''}</div><div class="member-list">${(state.studioUsers||[]).map(u=>`<article class="member-row"><span class="avatar">${esc(initials(u.name))}</span><div><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></div><span class="tag">${esc(u.role)}</span>${state.studio?.role==='admin'?`${button('Edit','edit-studio-user','small',`data-id="${esc(u.id)}"`)}${button('Remove','remove-studio-user','small danger-text',`data-id="${esc(u.id)}"`)}`:''}</article>`).join('')}</div>`;}
function studioUserModal(id){const u=(state.studioUsers||[]).find(u=>u.id===id)||{};openModal(u.id?'Edit studio member':'Add studio member',`<p>Members sign in with their own email. Existing accounts can belong to several studios.</p><form data-form="studio-user"><input type="hidden" name="id" value="${esc(u.id||'')}"><label>Name in this studio<input name="name" value="${esc(u.name||'')}" required maxlength="100"></label><label>Email<input type="email" name="email" value="${esc(u.email||'')}" ${u.id?'readonly':''} required></label><label>Role<select name="role"><option value="member" ${u.role!=='admin'?'selected':''}>Member</option><option value="admin" ${u.role==='admin'?'selected':''}>Admin · can manage users</option></select></label>${formFooter(u.id?'Save member':'Add member')}</form>`);}
let teamPicker={users:[],selected:new Set()};
async function projectTeamModal(){teamPicker={users:(await api('studio_users')).users,selected:new Set((state.data.members||[]).map(u=>u.id))};openModal('Project team',`<p>Search by name or email to add people. Only this team can edit the project.</p><form data-form="project-team"><div id="team-selected" class="team-selected"></div><label>Find studio members<input id="team-search" type="search" placeholder="Search name or email" autocomplete="off"></label><div id="team-results" class="team-results"></div>${formFooter('Save team')}</form>`);renderTeamPicker();}
function renderTeamPicker(){const search=($('#team-search')?.value||'').trim().toLowerCase(),selected=teamPicker.users.filter(u=>teamPicker.selected.has(u.id)),matches=teamPicker.users.filter(u=>!teamPicker.selected.has(u.id)&&(`${u.name} ${u.email}`).toLowerCase().includes(search));$('#team-selected').innerHTML=`<p>${selected.length} team member${selected.length===1?'':'s'}</p><div class="row wrap">${selected.map(u=>button(`${esc(u.name)} ${icon('close')}`,'team-remove','small',`data-id="${esc(u.id)}" aria-label="Remove ${esc(u.name)} from team"`)).join('')}</div>`;$('#team-results').innerHTML=matches.slice(0,20).map(u=>`<button type="button" class="team-result" data-action="team-add" data-id="${esc(u.id)}"><span><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></span>${icon('plus')}</button>`).join('')+`<p class="form-hint">${matches.length>20?`${matches.length} matches · Refine your search to find more people.`:matches.length?'Select a person to add them.':'No matching members.'}</p>`;}
document.addEventListener('input',e=>{if(e.target.id==='team-search')renderTeamPicker();});
document.addEventListener('change',async e=>{if(e.target.id==='studio-select'){try{applySession(await api('switch_studio',{studio_id:e.target.value}));await resetStudio();}catch(error){toast(error.message);}}});

function projectLogoFallback(){return state.studio?.has_logo?`<img class="studio-logo" src="${studioLogoUrl()}" alt="Studio logo">`:defaultBrand();}
function projectSettingsModal(){
    const p=state.data.project;
    openModal('Project settings',`<form data-form="project-settings" class="project-settings-content">
        <div class="project-settings-fields">
            <label>Project labels<input name="tags" value="${esc((p.tags||[]).join(', '))}" placeholder="Residential, Renovation, Priority" maxlength="820"><span class="form-hint">Separate labels with commas. Search for them on All projects.</span></label>
            <div class="project-visibility"><label class="check-label"><input type="checkbox" role="switch" name="team_only" ${p.visibility!=='public'?'checked':''} aria-describedby="visibility-description">Team members only</label><p id="visibility-description" class="form-hint">${p.visibility==='public'?'Everyone in the studio can view.':'Only the project team can view.'} Only the project team can edit.</p></div>
        </div>
        <section class="project-settings-logo">
            <div class="row"><h3>Presentation logo</h3><span class="logo-help"><button type="button" class="icon-button" aria-label="How the presentation logo is chosen" aria-describedby="logo-priority-tooltip">${icon('help')}</button><span role="tooltip" id="logo-priority-tooltip">Project logo first, then studio logo, then Studiodeck.</span></span></div>
            <div class="dropzone project-logo-dropzone" data-project-logo-drop><button type="button" class="project-logo-picker" data-action="choose-project-logo" aria-label="Choose presentation logo"><span class="project-settings-logo-preview" data-logo-preview>${state.data.branding?.logo?`<img class="studio-logo" src="${esc(state.data.branding.logo)}" alt="Current presentation logo">`:defaultBrand()}</span><span>Drop a logo here, or <u>browse</u></span><small>PNG, JPEG or WebP · up to 2 MB</small></button><input type="file" id="project-logo-input" name="logo" accept="image/png,image/jpeg,image/webp" hidden></div>
            <small data-logo-status role="status">Click the logo to change it. Changes are applied when you save.</small>
            ${button('Remove project logo','clear-project-logo','small ghost',state.data.branding?.has_project_logo?'':'hidden')}
        </section>
        ${formFooter('Save settings')}
    </form>`);
    const form=$('[data-form="project-settings"]'),zone=form.querySelector('[data-project-logo-drop]');
    form.querySelector('[name="team_only"]').addEventListener('change',e=>{form.querySelector('#visibility-description').textContent=(e.target.checked?'Only the project team can view.':'Everyone in the studio can view.')+' Only the project team can edit.';});
    form.querySelector('#project-logo-input').addEventListener('change',e=>stageProjectLogo([...e.target.files],form));
    zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging');});
    zone.addEventListener('dragleave',e=>{if(!zone.contains(e.relatedTarget))zone.classList.remove('dragging');});
    zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragging');stageProjectLogo([...e.dataTransfer.files],form);});
}
async function stageProjectLogo(files,form){
    const status=form.querySelector('[data-logo-status]'),file=files[0];if(!file)return;
    if(files.length!==1){status.textContent='Choose one logo image at a time.';return;}
    if(file.size>2*1024*1024){status.textContent='This logo is too large. Choose an image up to 2 MB.';return;}
    if(!['image/png','image/jpeg','image/webp'].includes(file.type)){status.textContent='Choose a PNG, JPEG or WebP logo.';return;}
    const pick=form._logoPick=(form._logoPick||0)+1,submit=form.querySelector('[type="submit"]');form._logoLoading=true;submit.disabled=true;status.textContent='Preparing logo preview…';
    try{
        const url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});
        const image=new Image();image.src=url;await image.decode();if(image.naturalWidth*image.naturalHeight>12000000)throw Error('Choose an image up to 12 megapixels.');
        if(!form.isConnected||pick!==form._logoPick)return;
        form._logoFile=file;form._removeLogo=false;image.alt='Selected presentation logo';image.className='studio-logo';form.querySelector('[data-logo-preview]').replaceChildren(image);form.querySelector('[data-action="clear-project-logo"]').hidden=false;status.textContent=`${file.name} · ${bytes(file.size)} · Ready to save`;
    }catch(error){if(form.isConnected&&pick===form._logoPick)status.textContent=error.message||'This image could not be opened. Please choose another logo.';}
    finally{if(pick===form._logoPick){form._logoLoading=false;submit.disabled=false;}}
}
document.addEventListener('input',e=>{if(e.target.id==='project-search'){state.projectSearch=e.target.value;$('#project-grid').innerHTML=projectTiles();hydrateProjectCovers();syncWorkspaceUrl(true);}});
document.addEventListener('change',async e=>{if(e.target.id==='show-archived'){state.showArchived=e.target.checked;try{await loadProjects();$('#project-grid').innerHTML=projectTiles();hydrateProjectCovers();syncWorkspaceUrl(true);pollJobs();}catch(error){toast(error.message);}}});

const builtinSlideTitles={intro:'Welcome home',changes:'What’s new',budget:'The investment',contacts:'Your project team',summary:'Everything, together',general:'General comment'};
async function loadFeed(more=false){const comments=state.tab!=='all-activity',project=state.tab==='comments'?state.data.project.id:null;const result=await api(comments?'comments_feed':'activity_feed',{offset:more?(state.feedItems||[]).length:0,project_id:project});state.feedItems=more?[...(state.feedItems||[]),...result.items]:result.items;state.feedMore=result.has_more;if(comments)state.unreadCount=result.unread_count??state.unreadCount;}
function feedPage(projectOnly=false){const comments=state.tab!=='all-activity',items=state.feedItems||[];return `<div class="section-title"><div><h${projectOnly?'2':'1'}>${comments?'Comments':'Project activity'}</h${projectOnly?'2':'1'}><p class="muted">Newest first · ${projectOnly?'All iterations of this project':'Across your accessible projects in this studio'}</p></div></div><div class="timeline">${items.map(item=>comments?`<article class="timeline-item comment-card">${commentPreview(item)}<div>${commentAuthor(item)}<h3>${esc(item.project_name)} · Iteration ${item.iteration_number}</h3><p class="comment-body">${esc(item.body)}</p>${button(item.slide==='general'?'Open iteration':`View slide · ${esc(item.slide_title||builtinSlideTitles[item.slide]||'Source slide')}`,'comment-slide','small ghost',`data-project="${esc(item.project_id)}" data-iteration="${esc(item.iteration_id)}" data-slide="${esc(item.slide)}"`,'slide')}</div></article>`:`<article class="timeline-item"><span class="event-icon">${icon('activity')}</span><div><small>${esc(date(item.created_at))} · ${esc(item.actor)}</small><h3>${esc(item.project_name)}</h3>${activityDetail(item)}${button('Open project activity','activity-project','small ghost',`data-project="${esc(item.project_id)}" data-iteration="${esc(item.iteration_id||'')}"`,'arrow')}</div></article>`).join('')||'<p class="notice">Nothing here yet.</p>'}</div>${state.feedMore?button('Load more','more-feed','','','down'):''}`;}
async function openCommentSlide(data){state.tab='overview';await openProject(data.project,data.iteration);if(data.slide==='general'){feedbackModal();return;}state.inspectHidden=true;const defs=slideDefs(),index=defs.findIndex(s=>s.id===data.slide);if(index<0){openModal('Source slide unavailable','<p>This slide was removed from its iteration. Its comment remains in the comments list.</p>');return;}startPresentation(index);feedbackModal();}

function personAvatar(profile={},name=''){return `<span class="avatar person-avatar" ${profile?.color?`style="background:${esc(profile.color)};color:${personalText(profile.color)}"`:''}>${profile?.avatar?`<img src="${esc(profile.avatar)}" alt="">`:esc(initials(profile?.name||name))}</span>`;}
function personalText(color){const rgb=[1,3,5].map(i=>parseInt(color.slice(i,i+2),16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return rgb.reduce((n,v,i)=>n+v*[.2126,.7152,.0722][i],0)>.179?'#151915':'#ffffff';}

function profilePage(client=false){const p=state.profile||state.user?.profile||{};return `<div class="profile-page"><h${client?'2':'1'}>${client?'Your preferences':'User profile'}</h${client?'2':'1'}><p class="muted">Your name, avatar and communication preferences.</p><div class="profile-avatar-editor">${personAvatar(p,p.name)}<form data-form="avatar"><label>Avatar<input type="file" name="avatar" accept="image/png,image/jpeg,image/webp" required></label><small>PNG, JPEG or WebP · up to 2 MB</small><button class="button small" type="submit">Upload avatar</button>${p.avatar?button('Remove avatar','remove-avatar','small'):''}</form></div><form data-form="profile"><label>Display name<input name="name" value="${esc(p.name||state.user?.name||'')}" required maxlength="100"></label><label class="check-label"><input type="checkbox" name="use_color" ${p.color?'checked':''}>Use my own profile color</label><label>Personal color<input type="color" name="color" value="${esc(p.color||'#465441')}"></label><p class="form-hint">Used for your avatar and comments. Presentation colors stay with the project.</p><fieldset><legend>Communication preferences</legend><label class="check-label"><input type="checkbox" name="email_comments" ${p.email_comments!==false?'checked':''}>Email me when someone else comments on my projects</label><p class="form-hint">You can change this preference anytime.</p>${(state.data?.capabilities||state.capabilities)?.mail===false?'<p class="notice">Email delivery is not configured for this installation yet. Your preference is saved for when delivery is connected.</p>':''}</fieldset>${formFooter('Save profile')}</form></div>`;}
async function showProfile(){const r=await api('profile');state.profile=r.profile;if(state.client)openModal('Your profile',profilePage(true));else{state.present=false;state.tab='profile';render();}}
async function reloadProfile(){const r=await api('profile');state.profile=r.profile;if(state.client){state.data.profile=r.profile;openModal('Your profile',profilePage(true));}else{state.user.profile=r.profile;render();}}
function commentAuthor(c){return `<div class="comment-author">${personAvatar(c.profile,c.author)}<small><strong>${esc(c.profile?.name||c.author)}</strong> · ${esc(date(c.created_at))}</small>${c.unread?`<span class="unread-badge" data-unread="${esc(c.id)}">Unread</span>`:''}</div>`;}
function commentPreview(c){const attrs=c.project_id?`data-action="comment-slide" data-project="${esc(c.project_id)}" data-iteration="${esc(c.iteration_id)}" data-slide="${esc(c.slide)}"`:'disabled';return `<button class="comment-preview" type="button" ${attrs} aria-label="Open commented slide"><img data-comment-preview="${esc(c.id)}" alt="${esc(c.slide_title||builtinSlideTitles[c.slide]||'Slide preview')}" loading="lazy"></button>`;}
async function hydrateCommentPreviews(){for(const im of document.querySelectorAll('[data-comment-preview]')){const id=im.dataset.commentPreview,key='comment-'+id;if(im.dataset.loading)continue;im.dataset.loading='1';try{let url=imageCache.get(key);if(!url){const r=await fetch('api.php?'+new URLSearchParams({action:'comment_preview',id}),{credentials:'same-origin',headers:state.shareToken?{Authorization:'Bearer '+state.shareToken}:state.studio?.id?{'X-Studio-ID':state.studio.id}:{}});if(!r.ok)continue;url=URL.createObjectURL(await r.blob());imageCache.set(key,url);}im.src=url;}catch{im.alt='Slide preview unavailable';}}}
async function markCommentsRead(comments){const ids=comments.filter(c=>c.unread).map(c=>c.id);for(let n=0;n<ids.length;n+=100)await api('read_comments',{ids:ids.slice(n,n+100)});if(!ids.length)return;for(const c of [...(state.data?.comments||[]),...(state.feedItems||[])])if(ids.includes(c.id))c.unread=false;document.querySelectorAll('[data-unread]').forEach(el=>{if(ids.includes(el.dataset.unread))el.remove();});if(!state.client)state.unreadCount=(await api('session')).unread_count||0;const balloon=$('.comment-balloon');if(balloon)balloon.innerHTML=icon('chat')+`${comments.length} comments`;}

function presentationTeam(data){const team=(data.team||data.members||[]).map(m=>({...m,role:'Design team'})),emails=new Set(team.map(m=>m.email.toLowerCase()));return [...team,...data.contacts.filter(c=>c.role!=='Client'&&!emails.has(c.email.toLowerCase()))];}


document.addEventListener('change',e=>{if(!e.target.matches('input[type=file]')||['wizard-file-input','project-logo-input'].includes(e.target.id))return;const label=e.target.closest('label')||e.target.parentElement;label.querySelector('.upload-selection')?.remove();if(e.target.files.length){const summary=document.createElement('span');summary.className='upload-selection';summary.setAttribute('role','status');summary.textContent=[...e.target.files].map(f=>`${f.name} · ${bytes(f.size)}`).join(', ');label.append(summary);}});
